const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',plus:'<rect x="3" y="3" width="18" height="18" rx="5"/><path d="M12 7v10M7 12h10"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',comment:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.5A9 9 0 0 1 4 11.5 8.5 8.5 0 0 1 12.5 3h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const users={usr_alex:{id:'usr_alex',name:'Alex Kim',handle:'alex',initials:'AK',color:'you'},usr_mira:{id:'usr_mira',name:'Mira Santos',handle:'mira.s',initials:'MS',color:'mira'},usr_jules:{id:'usr_jules',name:'Jules Park',handle:'jules.jpg',initials:'JP',color:'jules'}};
const currentUser='usr_alex';
let posts=[{id:'pst_mira',userId:'usr_mira',content:'Collecting little moments, not things. Take the long way home today. ☀',visual:'photo',art:'little moments.\nbig energy.',theme:'pink',createdAt:new Date(Date.now()-35*60000).toISOString(),likes:[],baseLikes:128,comments:[{id:'cmt_seed',userId:'usr_jules',content:'This is the reminder I needed.',createdAt:new Date().toISOString()}]},{id:'pst_alex',userId:'usr_alex',content:'A reminder to make something just because it makes you happy. What did you create today?',visual:'text',art:'make something.\nfeel something.',theme:'blue',createdAt:new Date(Date.now()-70*60000).toISOString(),likes:[],baseLikes:24,comments:[]},{id:'pst_jules',userId:'usr_jules',content:'Offline for a bit. Back with a pocket full of ideas. ✨',visual:'text',art:'less scrolling.\nmore living.',theme:'teal',createdAt:new Date(Date.now()-140*60000).toISOString(),likes:[],baseLikes:86,comments:[]}];
let notifications=[],view='feed',requests=[];
function avatar(u){return `<span class="avatar ${u.color}">${u.initials}</span>`;}
function timeAgo(date){const m=Math.max(0,Math.floor((Date.now()-new Date(date).getTime())/60000));return m<1?'Just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;}
function postCard(p,index){const u=users[p.userId],liked=p.likes.includes(currentUser);return `<article class="post-card" id="${p.id}" style="--index:${index}"><div class="post-top">${avatar(u)}<div class="post-author"><strong>${u.name}</strong><small>@${u.handle}</small></div><span class="post-time">${timeAgo(p.createdAt)}</span>${p.userId===currentUser?`<button class="icon-button" data-action="delete" data-id="${p.id}" aria-label="Delete your post">${icon('trash')}</button>`:''}</div><div class="post-media ${p.visual==='photo'?'photo':''}" data-media="${p.id}">${p.visual==='photo'?'<img src="assets/coastal-moment.png" alt="An adult skateboarder on a coastal promenade in sunset light"><span class="media-corner">A LITTLE OUTSIDE</span><span class="photo-label">take the<br>long way.</span>':`<div class="text-art ${p.theme}"><span class="media-corner">${p.userId===currentUser?'FROM YOUR WORLD':'LITTLE MOMENTS'}</span><div class="art-text">${esc(p.art)}</div><span class="art-star" aria-hidden="true">✳</span></div>`}<span class="media-heart" aria-hidden="true">♥</span></div><div class="post-body"><div class="post-actions"><button class="action ${liked?'liked':''}" data-action="like" data-id="${p.id}" aria-label="${liked?'Liked':'Like'} post by ${u.name}" aria-pressed="${liked}">${icon('heart')}<span>${p.baseLikes+p.likes.length}</span></button><button class="action" data-action="comments" data-id="${p.id}" aria-label="Comment on post by ${u.name}">${icon('comment')}<span>${p.comments.length}</span></button><span class="double-hint">Double tap to like</span></div><p class="post-caption"><strong>${u.handle}</strong>${esc(p.content)}</p><div class="comments-preview">${p.comments.slice(-1).map(c=>`<p class="comment-line"><strong>${users[c.userId].handle}</strong>${esc(c.content)}</p>`).join('')}</div><button class="comments-link" data-action="comments" data-id="${p.id}">${p.comments.length?'View comments':'Be the first to comment'}</button></div></article>`;}
function renderFeed(){document.querySelector('#main').innerHTML=`<div class="feed-header"><h1>In the loop.</h1><span class="feed-label">Your feed</span></div><div class="composer-prompt">${avatar(users[currentUser])}<button data-action="compose">What’s on your mind, Alex?</button><span class="prompt-icon">${icon('plus')}</span></div><div id="posts">${posts.map(postCard).join('')}</div><div class="screen-footer">Little moments, all caught up. · Round 2 demo</div>`;}
document.querySelector('#activity-preview').innerHTML='<div class="activity-empty">No notifications yet.<br>Like or comment on a post to see one arrive.</div>';
renderFeed();
const storageKey='loop-social-round2-v1';
try{const state=JSON.parse(localStorage.getItem(storageKey)||'null');if(state&&Array.isArray(state.posts)&&Array.isArray(state.notifications)){const valid=state.posts.every(p=>p&&/^pst_[a-zA-Z0-9_-]+$/.test(p.id)&&users[p.userId]&&typeof p.content==='string'&&p.content.length<=500&&typeof p.art==='string'&&p.art.length<=200&&['pink','blue','teal'].includes(p.theme)&&['text','photo'].includes(p.visual)&&Number.isFinite(Date.parse(p.createdAt))&&Array.isArray(p.likes)&&p.likes.every(u=>users[u])&&Number.isFinite(p.baseLikes)&&p.baseLikes>=0&&Array.isArray(p.comments)&&p.comments.every(c=>users[c.userId]&&typeof c.content==='string'&&c.content.length<=300));if(valid){posts=state.posts;notifications=state.notifications.filter(n=>n&&users[n.recipientId]&&users[n.actorId]&&['like','comment'].includes(n.type)&&typeof n.postId==='string'&&typeof n.id==='string'&&Number.isFinite(Date.parse(n.createdAt)));}}}catch{}
const modal=document.querySelector('#modal'),main=document.querySelector('#main');
function save(){try{localStorage.setItem(storageKey,JSON.stringify({posts,notifications}));}catch{toast('Changes work for this visit; browser storage is unavailable.');}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3300);}
function publicPost(p){return {id:p.id,userId:p.userId,content:p.content,createdAt:p.createdAt,likeCount:p.baseLikes+p.likes.length,commentCount:p.comments.length};}
function notify(type,p){const n={id:`ntf_${crypto.randomUUID()}`,type,postId:p.id,actorId:currentUser,recipientId:p.userId,createdAt:new Date().toISOString()};notifications.unshift(n);notifications.splice(50);return n;}
function api(method,path,body={}){
 const parts=path.split('?')[0].split('/').filter(Boolean);let status=200,data=null;const p=posts.find(p=>p.id===parts[2]);
 const fail=(code,message)=>{status=code;data={error:{code:message.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message}};};
 if(method==='GET'&&parts[1]==='users'&&parts[3]==='feed'&&parts.length===4){if(parts[2]!==currentUser)fail(403,'You can only view the demo user feed');else data={userId:currentUser,order:'newest_first',posts:[...posts].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt)).map(publicPost)};}
 else if(method==='POST'&&path==='/api/posts'){
  if(!body.userId||!Object.hasOwn(body,'content'))fail(400,'userId and content are required');
  else if(body.userId!==currentUser)fail(403,'User does not match the demo identity');
  else if(typeof body.content!=='string'||!body.content.trim()||body.content.length>500)fail(422,'Write a post between 1 and 500 characters');
  else{status=201;const c=body.content.trim();const newPost={id:`pst_${crypto.randomUUID()}`,userId:currentUser,content:c,visual:'text',art:c.length>120?c.slice(0,117)+'…':c,theme:['pink','blue','teal'][posts.filter(p=>p.userId===currentUser).length%3],createdAt:new Date().toISOString(),likes:[],baseLikes:0,comments:[]};posts.unshift(newPost);data=publicPost(newPost);save();}
 }
 else if(parts[1]==='posts'&&parts[2]){
  if(!p)fail(404,'Post not found');
  else if(method==='POST'&&parts[3]==='likes'&&parts.length===4){
   if(!body.userId)fail(400,'userId is required');else if(body.userId!==currentUser)fail(403,'User does not match the demo identity');else if(p.likes.includes(currentUser))fail(409,'You already liked this post');else{status=201;p.likes.push(currentUser);const notification=notify('like',p);data={postId:p.id,userId:currentUser,liked:true,likeCount:p.baseLikes+p.likes.length,notificationId:notification.id};save();}
  }
  else if(method==='POST'&&parts[3]==='comments'&&parts.length===4){
   if(!body.userId||!Object.hasOwn(body,'content'))fail(400,'userId and content are required');else if(body.userId!==currentUser)fail(403,'User does not match the demo identity');else if(typeof body.content!=='string'||!body.content.trim()||body.content.length>300)fail(422,'Write a comment between 1 and 300 characters');else{status=201;const comment={id:`cmt_${crypto.randomUUID()}`,userId:currentUser,content:body.content.trim(),createdAt:new Date().toISOString()};p.comments.push(comment);const notification=notify('comment',p);data={...comment,postId:p.id,notificationId:notification.id};save();}
  }
  else if(method==='DELETE'&&parts.length===3){if(p.userId!==currentUser)fail(403,'Only the author can delete this post');else{status=204;posts=posts.filter(item=>item.id!==p.id);notifications=notifications.filter(n=>n.postId!==p.id);data=null;save();}}
  else fail(404,'Endpoint not found');
 }else fail(404,'Endpoint not found');
 requests.unshift({method,path,status,request:body,response:data});requests.splice(40);return {status,data};
}
function notificationHtml(n){const u=users[n.actorId],recipient=users[n.recipientId];return `<div class="notification-item"><span class="notification-icon">${icon(n.type==='like'?'heart':'comment')}</span><div><p><strong>@${u.handle}</strong> ${n.type==='like'?'liked':'commented on'} a post.<br>Delivered to <strong>@${recipient.handle}</strong>.</p><small>${timeAgo(n.createdAt)} · Simulated delivery</small></div></div>`;}
function updateNotifications(){document.querySelector('#notification-count').textContent=notifications.length;document.querySelector('#activity-preview').innerHTML=notifications.length?notifications.slice(0,3).map(notificationHtml).join(''):'<div class="activity-empty">No notifications yet.<br>Like or comment on a post to see one arrive.</div>';}
function regenerateFeed(){api('GET',`/api/users/${currentUser}/feed`);if(view==='feed')renderFeed();updateNotifications();}
function showView(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#breadcrumb').textContent={feed:'Your feed',activity:'Notifications',api:'Round 2 API design'}[view];document.querySelector('.content-layout').classList.toggle('api-mode',view==='api');if(view==='feed'){api('GET',`/api/users/${currentUser}/feed`);renderFeed();}else if(view==='activity')renderActivity();else renderApi();location.hash=view;window.scrollTo({top:0,behavior:'instant'});}
function modalHeading(title){return `<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function compose(){const u=users[currentUser];openModal(`${modalHeading('A little moment to share.')}<form id="post-form"><div class="modal-body"><div class="modal-user">${avatar(u)}<div><strong>${u.name}</strong><small>@${u.handle}</small></div></div><label class="field-label" for="post-content">What’s on your mind?</label><textarea id="post-content" maxlength="500" placeholder="A thought, a moment, a little something…" autofocus></textarea><div class="character-count" id="post-count">0 / 500</div><p class="form-note">Your words become a colorful post in the feed.<br>Demo posts are saved in this browser only.</p><div id="post-error" role="alert"></div></div><div class="modal-footer"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="primary">Publish post</button></div></form>`);document.querySelector('#post-content').focus();}
function openComments(id){const p=posts.find(p=>p.id===id);if(!p)return toast('This post is no longer available.');openModal(`${modalHeading('Keep the conversation going.')}<div class="modal-body"><div class="all-comments">${p.comments.length?p.comments.map(c=>{const u=users[c.userId];return `<div class="full-comment">${avatar(u)}<p><strong>@${u.handle}</strong>${esc(c.content)}</p></div>`;}).join(''):'<div class="activity-empty">No comments yet. Say something kind.</div>'}</div><form id="comment-form" data-id="${id}"><label class="field-label" for="comment-content">Your comment</label><div class="comment-form"><input id="comment-content" maxlength="300" placeholder="Add a comment…" autocomplete="off"><button class="primary" type="submit">Post</button></div><div id="comment-error" role="alert"></div></form></div><div class="modal-footer"><span class="form-note" style="margin:0">Up to 300 characters.</span><button class="secondary" data-action="close">Done</button></div>`);document.querySelector('#comment-content').focus();}
function deleteDialog(id){const p=posts.find(p=>p.id===id);if(!p)return toast('This post is no longer available.');if(p.userId!==currentUser)return toast('Only the author can delete this post.');openModal(`${modalHeading('Delete this post?')}<div class="modal-body"><div class="delete-preview">${esc(p.content)}</div><p class="delete-note">This removes your demo post, its likes, comments, and related notification records from this browser.</p></div><div class="modal-footer"><button class="secondary" data-action="close">Keep post</button><button class="danger" data-action="confirm-delete" data-id="${id}">Delete post</button></div>`);}
function like(id){const r=api('POST',`/api/posts/${id}/likes`,{userId:currentUser});if(r.status!==201&&r.status!==409)return toast(r.data.error.message);const p=posts.find(p=>p.id===id),card=document.getElementById(id);if(card){const button=card.querySelector('[data-action=like]');button.classList.add('liked');button.setAttribute('aria-pressed','true');button.setAttribute('aria-label',`Liked post by ${users[p.userId].name}`);button.querySelector('span').textContent=p.baseLikes+p.likes.length;button.classList.remove('pop');void button.offsetWidth;button.classList.add('pop');const heart=card.querySelector('.media-heart');heart.classList.remove('burst');void heart.offsetWidth;heart.classList.add('burst');setTimeout(()=>heart.classList.remove('burst'),850);}updateNotifications();if(view==='activity')renderActivity();toast(r.status===201?`Liked. Demo notification delivered to @${users[p.userId].handle}.`:'You already liked this post.');}
function renderActivity(){main.innerHTML=`<section class="page-heading"><h1>A little connection.</h1><p>Like and comment events notify the post’s author. This list demonstrates delivery to each recipient; it is not a real push-notification service.</p></section><div class="activity-page">${notifications.length?notifications.map(notificationHtml).join(''):'<div class="empty-feed"><h2>Quiet for now.</h2><p>Like or comment on a post to send the first demo notification.</p><button class="primary" data-view="feed">View feed</button></div>'}</div>`;}
function renderApi(){const rows=[['POST','/api/posts','Create post','201 · 400 · 403 · 422'],['GET','/api/users/{userId}/feed','Get user feed','200 · 403'],['POST','/api/posts/{postId}/likes','Like post','201 · 400 · 403 · 404 · 409'],['POST','/api/posts/{postId}/comments','Add comment','201 · 400 · 403 · 404 · 422'],['DELETE','/api/posts/{postId}','Delete own post','204 · 403 · 404']];main.innerHTML=`<section class="page-heading"><span class="eyebrow">ROUND 2 · LOW-LEVEL DESIGN</span><h1 style="margin-top:12px">Behind the little moments.</h1><p>The five requested APIs, their contracts, status codes, and the user-to-notification sequence.</p></section><div class="api-notice">REST API design + browser simulation. Actions on this site simulate these endpoints in JavaScript. There is no HTTP API server, login service, or real push notification. One fixed demo user is used; records are saved in this browser.</div><div class="table-wrap"><table><thead><tr><th>METHOD</th><th>URI</th><th>PURPOSE</th><th>STATUS CODES</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="method ${r[0].toLowerCase()}">${r[0]}</span></td><td><code>${r[1]}</code></td><td>${r[2]}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table></div><div class="api-grid"><section class="api-panel"><h2>Create Post — request</h2><p>Creates a text post for the authenticated user. Content must contain 1–500 characters.</p><pre>POST /api/posts\nAuthorization: Bearer &lt;user-token&gt;\nContent-Type: application/json\n\n{\n  "userId": "usr_alex",\n  "content": "A little moment worth sharing."\n}</pre><p>Production design: derive the author from the token, or verify that userId matches it. A blank or oversized post returns 422.</p></section><section class="api-panel"><h2>Create Post — response</h2><p>201 Created · Location: /api/posts/pst_123</p><pre>{\n  "id": "pst_123",\n  "userId": "usr_alex",\n  "content": "A little moment worth sharing.",\n  "createdAt": "2026-10-09T07:00:00Z",\n  "likeCount": 0,\n  "commentCount": 0\n}</pre><p>The new post is stored and appears at the top of the generated feed. The response contains the new post identifier.</p></section><section class="api-panel api-full"><h2>User → notification</h2><ol><li><strong>Create Post:</strong> User → POST /api/posts with text content.</li><li><strong>Store Post:</strong> Validate author and content → save post → return 201 Created.</li><li><strong>Generate Feed:</strong> GET /api/users/usr_alex/feed → posts ordered newest first, including the new post.</li><li><strong>Like / Comment:</strong> POST /api/posts/{postId}/likes or /comments → store the interaction → return 201.</li><li><strong>Notification:</strong> Create a notification event for the post’s author → deliver it → show the simulated delivery in Notifications.</li></ol><p>The demo creates notification records synchronously. Production delivery should happen only after the interaction is stored successfully. Feed ranking, distributed services, queues, caching, and scaling belong to Round 3 and are outside this demo.</p></section><section class="api-panel"><h2>Like and comment contracts</h2><pre>POST /api/posts/pst_123/likes\n{"userId":"usr_alex"}\n\n201 Created\n{\n  "postId":"pst_123",\n  "userId":"usr_alex",\n  "liked":true,\n  "likeCount":1,\n  "notificationId":"ntf_123"\n}</pre><p>One like per user and post. A repeated like returns 409 and leaves the count unchanged.</p><pre>POST /api/posts/pst_123/comments\n{"userId":"usr_alex","content":"Love this!"}\n\n201 Created\n{\n  "id":"cmt_123",\n  "userId":"usr_alex",\n  "content":"Love this!",\n  "postId":"pst_123",\n  "createdAt":"2026-10-09T07:05:00Z",\n  "notificationId":"ntf_124"\n}</pre><p>Comments must contain 1–300 characters. Each successful interaction creates one notification record.</p></section><section class="api-panel"><h2>Feed and Delete Post</h2><pre>GET /api/users/usr_alex/feed\n\n200 OK\n{\n  "userId":"usr_alex",\n  "order":"newest_first",\n  "posts":[{\n    "id":"pst_123",\n    "userId":"usr_alex",\n    "content":"A little moment worth sharing.",\n    "createdAt":"2026-10-09T07:00:00Z",\n    "likeCount":0,\n    "commentCount":0\n  }]\n}</pre><pre>DELETE /api/posts/pst_123\nAuthorization: Bearer &lt;author-token&gt;\n\n204 No Content\n(no response body)</pre><p>Only the author can delete a post. Another user receives 403; an unknown or already-deleted post receives 404. The demo removes the post and associated likes, comments, and notification records, then regenerates the feed.</p></section><section class="api-panel api-full"><h2>Suitable HTTP status codes</h2><p><strong>200 OK</strong> — Feed retrieved. <strong>201 Created</strong> — Post, like, or comment created. <strong>204 No Content</strong> — Post deleted, with no response body. <strong>400 Bad Request</strong> — Required fields missing. <strong>403 Forbidden</strong> — Author mismatch or unauthorized deletion. <strong>404 Not Found</strong> — Post missing. <strong>409 Conflict</strong> — Duplicate like. <strong>422 Unprocessable Content</strong> — Blank, oversized, or invalid text.</p><p>Production API design also uses <strong>401 Unauthorized</strong> for missing/invalid authentication and <strong>500 Internal Server Error</strong> for unexpected server failures. These are design notes; authentication and server failures are not implemented in this frontend demo.</p><pre>{\n  "error": {\n    "code": "POST_NOT_FOUND",\n    "message": "Post not found"\n  }\n}</pre></section><section class="api-panel api-full"><h2>Live simulated request log</h2><p>Create, like, comment, or delete a post, then return here to inspect the corresponding request and response.</p><div class="request-log">${requests.map(r=>`<details><summary class="log-row"><span class="status ${r.status>=400?'error':''}">${r.status}</span><strong>${r.method}</strong><span>${esc(r.path)}</span></summary><pre>${esc(JSON.stringify({request:r.request,response:r.response},null,2))}</pre></details>`).join('')||'<p>No requests yet.</p>'}</div></section></div>`;}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.view){showView(b.dataset.view);return;}const id=b.dataset.id;switch(b.dataset.action){case 'compose':compose();break;case 'close':modal.close();break;case 'like':like(id);break;case 'comments':openComments(id);break;case 'delete':deleteDialog(id);break;case 'confirm-delete':{const r=api('DELETE',`/api/posts/${id}`);if(r.status===204){modal.close();const card=document.getElementById(id);if(card)card.classList.add('removing');setTimeout(()=>{regenerateFeed();if(view==='activity')renderActivity();},300);toast('Your post was deleted.');}else toast(r.data.error.message);break;}}});
document.addEventListener('dblclick',event=>{const media=event.target.closest('[data-media]');if(media&&Date.now()-lastTouchLikeAt>600)like(media.dataset.media);});
let lastTouch={id:null,time:0},lastTouchLikeAt=0;document.addEventListener('pointerup',event=>{if(event.pointerType!=='touch')return;const media=event.target.closest('[data-media]');if(!media)return;const now=Date.now();if(lastTouch.id===media.dataset.media&&now-lastTouch.time<300){event.preventDefault();lastTouchLikeAt=now;like(media.dataset.media);lastTouch={id:null,time:0};}else lastTouch={id:media.dataset.media,time:now};});
document.addEventListener('input',event=>{if(event.target.id==='post-content')document.querySelector('#post-count').textContent=`${event.target.value.length} / 500`;});
document.addEventListener('submit',event=>{if(event.target.id==='post-form'){event.preventDefault();const r=api('POST','/api/posts',{userId:currentUser,content:document.querySelector('#post-content').value});if(r.status===201){modal.close();showView('feed');toast('Posted. Your moment is in the feed.');}else document.querySelector('#post-error').innerHTML=`<p class="error-text">${esc(r.data.error.message)}</p>`;}else if(event.target.id==='comment-form'){event.preventDefault();const id=event.target.dataset.id,r=api('POST',`/api/posts/${id}/comments`,{userId:currentUser,content:document.querySelector('#comment-content').value});if(r.status===201){regenerateFeed();openComments(id);if(view==='activity')renderActivity();toast('Comment added. Demo notification delivered.');}else document.querySelector('#comment-error').innerHTML=`<p class="error-text">${esc(r.data.error.message)}</p>`;}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['feed','activity','api'].includes(next)&&next!==view)showView(next);});
updateNotifications();showView(['feed','activity','api'].includes(location.hash.slice(1))?location.hash.slice(1):'feed');
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'get_user_feed',title:'Read the social demo feed',description:'Read the fixed demo user feed, newest posts first. Does not create, like, comment, delete, or change the visible view.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input===null||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');const r=api('GET',`/api/users/${currentUser}/feed`);return r.data;}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
